      "query": "SELECT i.order_id, i.amount, i.vat, i.total, i.created_at FROM invoices i JOIN ledger l ON i.order_id = l.order_id WHERE l.vat != ROUND(l.amount * 0.15, 2) OR l.total != l.amount + l.vat ORDER BY i.created_at LIMIT 10",
      "why": "Check if the invoice data itself is correct before sync-job processes it, to determine if the fault is in invoice generation or ledger sync"
    }
  ],
  "hypotheses": [],
  "summary": "Investigating whether invoice data is correct before sync to isolate fault location"
